// Core tests: the 15 literal core cases from fixtures.json (expected
// values taken verbatim from the file, never generated by the product),
// plus hand-derived boundary, validation, and property cases from the
// SPEC's tests section. Every expected value below was computed by hand
// from the SPEC's rules.

import assert from "node:assert/strict";
import test from "node:test";
import {
  formatDistanceM,
  formatDuration,
  formatPace,
  run,
} from "../public/js/core/race.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}: ${entry.purpose}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

const base = { knownPreset: "10k", knownCustomM: "", knownTime: "40:00", targetCustomM: "" };

function errorOf(input) {
  const outcome = run(input);
  assert.equal(outcome.ok, false);
  return outcome.error;
}

test("legal endpoints: custom distance 42195 and total time 359999 seconds", () => {
  const outcome = run({
    knownPreset: "custom",
    knownCustomM: "42195",
    knownTime: "99:59:59",
    targetCustomM: "",
  });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.knownDistanceM, 42195);
  assert.equal(outcome.result.knownTimeSeconds, 359999);
  const marathon = outcome.result.predictions.find((row) => row.key === "marathon");
  assert.equal(marathon.predictedSeconds, 359999);
});

test("just over the limits: 42195.01 m and 360000 total seconds are RANGE", () => {
  assert.deepEqual(
    errorOf({ knownPreset: "custom", knownCustomM: "42195.01", knownTime: "40:00", targetCustomM: "" }),
    { code: "RANGE", field: "knownCustomM", row: null },
  );
  assert.deepEqual(errorOf({ ...base, knownTime: "100:00:00" }), {
    code: "RANGE",
    field: "knownTime",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, knownTime: "999:59:59" }), {
    code: "RANGE",
    field: "knownTime",
    row: null,
  });
});

test("time components: SS or MM of 60 is RANGE in both shapes; a total of 9 s is RANGE, 10 s is valid", () => {
  assert.deepEqual(errorOf({ ...base, knownTime: "1:60:00" }), {
    code: "RANGE",
    field: "knownTime",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, knownTime: "0:09" }), {
    code: "RANGE",
    field: "knownTime",
    row: null,
  });
  const tenSeconds = run({ knownPreset: "custom", knownCustomM: "400", knownTime: "0:10", targetCustomM: "" });
  assert.equal(tenSeconds.ok, true);
  assert.equal(tenSeconds.result.knownTimeSeconds, 10);
  const longMinutes = run({ ...base, knownTime: "999:59" });
  assert.equal(longMinutes.ok, true);
  assert.equal(longMinutes.result.knownTimeSeconds, 59999);
});

test("time grammar: three-digit SS, a four-digit first segment, and full-width digits are TIME_FORMAT", () => {
  assert.deepEqual(errorOf({ ...base, knownTime: "40:000" }), {
    code: "TIME_FORMAT",
    field: "knownTime",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, knownTime: "1000:00" }), {
    code: "TIME_FORMAT",
    field: "knownTime",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, knownTime: "４０:００" }), {
    code: "TIME_FORMAT",
    field: "knownTime",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, knownTime: "40-00" }), {
    code: "TIME_FORMAT",
    field: "knownTime",
    row: null,
  });
});

test("preset capacity precedes the enum check: a 9-unit preset is INPUT_LIMIT", () => {
  assert.deepEqual(errorOf({ ...base, knownPreset: "marathonx" }), {
    code: "INPUT_LIMIT",
    field: "knownPreset",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, knownPreset: "" }), {
    code: "EMPTY",
    field: "knownPreset",
    row: null,
  });
});

test("an inactive custom field is capacity-checked but otherwise ignored, even a lone surrogate", () => {
  assert.deepEqual(errorOf({ ...base, knownPreset: "5k", knownCustomM: "1234567890123" }), {
    code: "INPUT_LIMIT",
    field: "knownCustomM",
    row: null,
  });
  const ignored = run({ knownPreset: "5k", knownCustomM: "\uD800", knownTime: "20:00", targetCustomM: "" });
  const fiveK = fixtures.cases.find((entry) => entry.id === "five-k-source");
  assert.deepEqual(ignored, fiveK.expected);
});

test("an active custom field reports UNICODE before EMPTY and grammar", () => {
  assert.deepEqual(
    errorOf({ knownPreset: "custom", knownCustomM: "\uD800", knownTime: "40:00", targetCustomM: "" }),
    { code: "UNICODE", field: "knownCustomM", row: null },
  );
  assert.deepEqual(errorOf({ ...base, knownTime: "\uD800" }), {
    code: "UNICODE",
    field: "knownTime",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, knownTime: "" }), {
    code: "EMPTY",
    field: "knownTime",
    row: null,
  });
});

test("target custom distance: below-range values are RANGE, a marathon target adds a fifth row, last", () => {
  assert.deepEqual(errorOf({ ...base, targetCustomM: "0" }), {
    code: "RANGE",
    field: "targetCustomM",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, targetCustomM: "399.99" }), {
    code: "RANGE",
    field: "targetCustomM",
    row: null,
  });
  const outcome = run({ ...base, targetCustomM: "42195" });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.predictions.length, 5);
  const last = outcome.result.predictions[4];
  assert.equal(last.key, "custom");
  assert.equal(last.distanceM, 42195);
  assert.equal(last.predictedSeconds, 11040);
  const duplicate = run({ ...base, targetCustomM: "10000" });
  assert.equal(duplicate.result.predictions[4].predictedSeconds, 2400);
});

test("the first field in the fixed order reports first", () => {
  assert.deepEqual(errorOf({ knownPreset: "15k", knownCustomM: "", knownTime: "bad", targetCustomM: "" }), {
    code: "ENUM",
    field: "knownPreset",
    row: null,
  });
  assert.deepEqual(
    errorOf({ knownPreset: "custom", knownCustomM: "399", knownTime: "40:60", targetCustomM: "" }),
    { code: "RANGE", field: "knownCustomM", row: null },
  );
  assert.deepEqual(errorOf({ ...base, knownTime: "40:60", targetCustomM: "abc" }), {
    code: "RANGE",
    field: "knownTime",
    row: null,
  });
});

test("schema: extra key, missing key, wrong type, array, null, and accessor are all SCHEMA", () => {
  const schema = { code: "SCHEMA", field: null, row: null };
  assert.deepEqual(errorOf({ ...base, extra: "1" }), schema);
  const missing = { ...base };
  delete missing.knownTime;
  assert.deepEqual(errorOf(missing), schema);
  assert.deepEqual(errorOf({ ...base, knownTime: 2400 }), schema);
  assert.deepEqual(errorOf(["10k"]), schema);
  assert.deepEqual(errorOf(null), schema);
  assert.deepEqual(errorOf("10k"), schema);
  const withGetter = { ...base };
  Object.defineProperty(withGetter, "knownTime", {
    enumerable: true,
    get() {
      return "40:00";
    },
  });
  assert.deepEqual(errorOf(withGetter), schema);
});

test("property: for preset sources the known row's predictedSeconds equal the input seconds", () => {
  for (const entry of coreCases) {
    if (!entry.expected.ok) continue;
    const preset = entry.input.knownPreset;
    if (preset === "custom") continue;
    const row = entry.expected.result.predictions.find((candidate) => candidate.key === preset);
    assert.equal(row.predictedSeconds, entry.expected.result.knownTimeSeconds, entry.id);
    assert.equal(row.paceSecPerKm, entry.expected.result.knownPaceSecPerKm, entry.id);
  }
});

test("property: predictedSeconds never decrease as target distance grows", () => {
  const inputs = [
    base,
    { knownPreset: "5k", knownCustomM: "", knownTime: "20:00", targetCustomM: "30000" },
    { knownPreset: "marathon", knownCustomM: "", knownTime: "3:30:00", targetCustomM: "400" },
    { knownPreset: "custom", knownCustomM: "15000", knownTime: "1:07:30", targetCustomM: "21097.5" },
  ];
  for (const input of inputs) {
    const outcome = run(input);
    assert.equal(outcome.ok, true);
    const sorted = [...outcome.result.predictions].sort((a, b) => a.distanceM - b.distanceM);
    for (let i = 1; i < sorted.length; i += 1) {
      assert.ok(sorted[i].predictedSeconds >= sorted[i - 1].predictedSeconds);
    }
    const hasCustom = input.targetCustomM !== "";
    assert.equal(outcome.result.predictions.length, hasCustom ? 5 : 4);
    if (hasCustom) {
      assert.equal(outcome.result.predictions[outcome.result.predictions.length - 1].key, "custom");
    }
  }
});

test("display formatting: durations, paces, and grouped distances", () => {
  assert.equal(formatDuration(0), "0:00");
  assert.equal(formatDuration(59), "0:59");
  assert.equal(formatDuration(60), "1:00");
  assert.equal(formatDuration(110), "1:50");
  assert.equal(formatDuration(1151), "19:11");
  assert.equal(formatDuration(3599), "59:59");
  assert.equal(formatDuration(3600), "1:00:00");
  assert.equal(formatDuration(11040), "3:04:00");
  assert.equal(formatDuration(359999), "99:59:59");
  assert.equal(formatPace(230.2), "3:50");
  assert.equal(formatPace(240), "4:00");
  assert.equal(formatPace(275), "4:35");
  assert.equal(formatPace(298.6), "4:59");
  assert.equal(formatPace(305), "5:05");
  assert.equal(formatDistanceM(400), "400");
  assert.equal(formatDistanceM(5000), "5,000");
  assert.equal(formatDistanceM(21097.5), "21,097.5");
  assert.equal(formatDistanceM(42195), "42,195");
});
